function sync(){hidden.fields.value=JSON.stringify(selected);hidden.statuses.value=JSON.stringify(statuses);hidden.columns.value=JSON.stringify(columns);hidden.builder.value=JSON.stringify(builderConfig);hidden.email.value=JSON.stringify(emailConfig);hidden.additional.value=JSON.stringify(additionalEmails);hidden.integrations.value=JSON.stringify(integrations);document.getElementById('df-legacy-admin-template').value=emailConfig.admin.template||'standard';document.getElementById('df-legacy-user-template').value=emailConfig.user.template||'standard';}
function uniqueKey(base){base=String(base||'field').replace(/[^a-zA-Z0-9_]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase()||'field';let k=base,n=2;while(selected.some(x=>x.key===k))k=base+'_'+n++;return k;}
function defaultFieldConfig(x){x.config=x.config&&typeof x.config==='object'?x.config:{};x.config.layout={row:Number(x.config.layout?.row||selected.length+1),col:Number(x.config.layout?.col||1),width:Number(x.config.layout?.width||100),...(x.config.layout||{})};x.config.conditions=Array.isArray(x.config.conditions)?x.config.conditions:[];x.config.condition_logic=x.config.condition_logic||'all';x.config.condition_action=x.config.condition_action||'show';return x;}
selected=selected.map(defaultFieldConfig);
function add(item){const x=defaultFieldConfig(clone(item));x.key=uniqueKey(x.key);x.options=Array.isArray(x.options)?x.options:[];selected.push(x);renderSelected();renderColumns();renderTokens();renderUserEmailFields();}

// Accordion behavior.
document.querySelectorAll('[data-accordion]').forEach(section=>{const btn=section.querySelector('.df-section-toggle');btn?.addEventListener('click',()=>{const open=!section.classList.contains('is-open');if(window.matchMedia('(max-width:800px)').matches&&open){document.querySelectorAll('[data-accordion].is-open').forEach(x=>{if(x!==section){x.classList.remove('is-open');x.querySelector('.df-section-toggle')?.setAttribute('aria-expanded','false');}});}section.classList.toggle('is-open',open);btn.setAttribute('aria-expanded',open?'true':'false');});});

function renderLibrary(){filter.innerHTML='<option value="all"><?php echo addslashes(Text::_('COM_DECAROFORMS_CATEGORY_ALL')); ?></option>'+categoryOrder.map(c=>`<option value="${c}">${esc(tr.cats[c]||c)}</option>`).join('');const q=(search.value||'').trim().toLowerCase(),cat=filter.dataset.value||filter.value||'all';lib.innerHTML='';for(const category of categoryOrder){if(cat!=='all'&&cat!==category)continue;const items=library.filter(x=>x.category===category&&(!q||`${x.label} ${x.key} ${x.type}`.toLowerCase().includes(q)));if(!items.length)continue;const group=document.createElement('details');group.className='df-library-group';group.open=!!q||cat!=='all';group.innerHTML=`<summary><span>${esc(tr.cats[category]||category)}</span><span class="df-library-count">${items.length}</span></summary><div class="df-library-items"></div>`;const box=group.querySelector('.df-library-items');items.forEach(x=>{const d=document.createElement('div');d.className='df-lib-item';d.innerHTML=`<div><strong>${esc(x.label)}</strong><small>${esc(tr.types[x.type]||x.type)}</small></div><button class="df-add" type="button">${esc(tr.add)}</button>`;d.querySelector('button').onclick=()=>add(x);box.appendChild(d);});lib.appendChild(group);}}
filter.addEventListener('change',()=>{filter.dataset.value=filter.value;renderLibrary();});search.addEventListener('input',renderLibrary);

function fieldSelectOptions(current=''){return selected.map(f=>`<option value="${esc(f.key)}" ${f.key===current?'selected':''}>${esc(f.label)} (${esc(f.key)})</option>`).join('');}
