return h;}
function renderConditions(x,i){const c=x.config||{},rules=Array.isArray(c.conditions)?c.conditions:[];const rows=rules.map((r,ri)=>`<div class="df-condition-row"><select data-cond-field="${ri}"><option value="">—</option>${fieldSelectOptions(r.field||'')}</select><select data-cond-op="${ri}">${[['eq','='],['neq','≠'],['contains','contiene'],['not_contains','non contiene'],['empty','vuoto'],['not_empty','non vuoto'],['gt','>'],['lt','<'],['checked','selezionato'],['not_checked','non selezionato']].map(([v,l])=>`<option value="${v}" ${r.operator===v?'selected':''}>${l}</option>`).join('')}</select><input data-cond-value="${ri}" value="${esc(r.value||'')}" placeholder="Valore"><button type="button" data-cond-remove="${ri}">×</button></div>`).join('');return `<div class="df-config-panel"><div class="df-spread"><strong>${esc(tr.conditions)}</strong><button class="df-btn df-small" type="button" data-add-condition>+ ${esc(tr.addCondition)}</button></div><div class="df-config-grid" style="margin-top:8px"><div><label><?php echo addslashes(Text::_('COM_DECAROFORMS_CONDITION_ACTION')); ?></label><select data-cfg="condition_action"><option value="show" ${c.condition_action==='show'?'selected':''}>Mostra</option><option value="hide" ${c.condition_action==='hide'?'selected':''}>Nascondi</option><option value="require" ${c.condition_action==='require'?'selected':''}>Rendi obbligatorio</option><option value="disable" ${c.condition_action==='disable'?'selected':''}>Disabilita</option></select></div><div><label><?php echo addslashes(Text::_('COM_DECAROFORMS_CONDITION_LOGIC')); ?></label><select data-cfg="condition_logic"><option value="all" ${c.condition_logic!=='any'?'selected':''}>${esc(tr.all)}</option><option value="any" ${c.condition_logic==='any'?'selected':''}>${esc(tr.any)}</option></select></div></div><div class="df-condition-list">${rows||`<div class="df-note"><?php echo addslashes(Text::_('COM_DECAROFORMS_NO_CONDITIONS')); ?></div>`}</div></div>`;}
function renderSelected(){sel.innerHTML='';if(!selected.length){sel.innerHTML=`<div class="df-selected-empty">${esc(tr.empty)}</div>`;sync();return;}selected.forEach((x,i)=>{defaultFieldConfig(x);const d=document.createElement('div');d.className='df-selected-item';d.innerHTML=`<div class="df-selected-top"><div><strong>${i+1}. ${esc(x.label)}</strong><div class="df-note">${esc(tr.types[x.type]||x.type)} · ${esc(tr.key)}: ${esc(x.key)}</div></div><div class="df-mini-actions"><button type="button" data-act="up" title="${esc(tr.moveUp)}">↑</button><button type="button" data-act="down" title="${esc(tr.moveDown)}">↓</button><button type="button" data-act="remove" title="${esc(tr.remove)}">×</button></div></div><div class="df-selected-config"><div><label>${esc(tr.label)}</label><input data-k="label" value="${esc(x.label)}"></div><div><label>${esc(tr.key)}</label><input data-k="key" value="${esc(x.key)}"></div><div><label>${esc(tr.type)}</label><select data-k="type">${types.map(t=>`<option value="${t}" ${x.type===t?'selected':''}>${esc(tr.types[t]||t)}</option>`).join('')}</select></div><div><label>${esc(tr.placeholder)}</label><input data-k="placeholder" value="${esc(x.placeholder||'')}"></div><div><label>${esc(tr.default)}</label><input data-k="default" value="${esc(x.default||'')}"></div><div><label>${esc(tr.help)}</label><input data-k="help" value="${esc(x.help||'')}"></div><div class="full df-required"><input type="checkbox" data-k-check="required" ${x.required?'checked':''}><label>${esc(tr.required)}</label></div>${configHtml(x)}<div class="df-config-panel"><strong>${esc(tr.layout)}</strong><div class="df-config-grid" style="margin-top:7px"><div><label><?php echo addslashes(Text::_('COM_DECAROFORMS_ROW')); ?></label><input type="number" min="1" data-cfg="layout.row" value="${esc(x.config.layout.row||1)}"></div><div><label><?php echo addslashes(Text::_('COM_DECAROFORMS_COLUMN')); ?></label><input type="number" min="1" max="4" data-cfg="layout.col" value="${esc(x.config.layout.col||1)}"></div><div><label><?php echo addslashes(Text::_('COM_DECAROFORMS_WIDTH')); ?> %</label><input type="number" min="0" max="100" data-cfg="layout.width" value="${esc(x.config.layout.width||100)}"></div></div></div>${renderConditions(x,i)}</div>`;
 d.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('input',()=>{const k=el.dataset.k;if(k==='options')x.options=el.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);else x[k]=el.value;sync();if(k==='label'){d.querySelector('.df-selected-top strong').textContent=`${i+1}. ${x.label}`;renderColumns();renderTokens();renderUserEmailFields();renderAdditional();}if(k==='type'){renderSelected();renderColumns();renderUserEmailFields();}}));
 d.querySelectorAll('[data-k-check]').forEach(el=>el.addEventListener('change',()=>{x[el.dataset.kCheck]=el.checked;sync();}));
 d.querySelectorAll('[data-cfg]').forEach(el=>{const ev=el.tagName==='SELECT'?'change':'input';el.addEventListener(ev,()=>{setDeep(x.config,el.dataset.cfg,el.type==='number'?Number(el.value):el.value);sync();});});
 d.querySelectorAll('[data-cfg-check]').forEach(el=>el.addEventListener('change',()=>{setDeep(x.config,el.dataset.cfgCheck,el.checked);sync();}));
 d.querySelector('[data-act="up"]').onclick=()=>{if(i>0){[selected[i-1],selected[i]]=[selected[i],selected[i-1]];renderSelected();}};d.querySelector('[data-act="down"]').onclick=()=>{if(i<selected.length-1){[selected[i+1],selected[i]]=[selected[i],selected[i+1]];renderSelected();}};d.querySelector('[data-act="remove"]').onclick=()=>{selected.splice(i,1);renderSelected();renderColumns();renderTokens();renderUserEmailFields();renderAdditional();};
 d.querySelector('[data-add-condition]')?.addEventListener('click',()=>{x.config.conditions.push({field:'',operator:'eq',value:''});renderSelected();});d.querySelectorAll('[data-cond-field]').forEach(el=>el.addEventListener('change',()=>{x.config.conditions[Number(el.dataset.condField)].field=el.value;sync();}));d.querySelectorAll('[data-cond-op]').forEach(el=>el.addEventListener('change',()=>{x.config.conditions[Number(el.dataset.condOp)].operator=el.value;sync();}));d.querySelectorAll('[data-cond-value]').forEach(el=>el.addEventListener('input',()=>{x.config.conditions[Number(el.dataset.condValue)].value=el.value;sync();}));d.querySelectorAll('[data-cond-remove]').forEach(el=>el.addEventListener('click',()=>{x.config.conditions.splice(Number(el.dataset.condRemove),1);renderSelected();}));sel.appendChild(d);});sync();}

// Layout.
const layoutColumns=document.getElementById('df-layout-columns'),layoutWidths=document.getElementById('df-layout-widths'),layoutTotal=document.getElementById('df-layout-total'),mobileStack=document.getElementById('df-layout-mobile-stack');
function renderLayout(){let n=Math.max(1,Math.min(4,Number(builderConfig.layout.columns||1)));builderConfig.layout.columns=n;layoutColumns.value=String(n);mobileStack.checked=builderConfig.layout.mobile_stack!==false;let widths=Array.isArray(builderConfig.layout.widths)?builderConfig.layout.widths.slice(0,n).map(Number):[];while(widths.length<n)widths.push(Math.floor(100/n));if(widths.length&&widths.reduce((a,b)=>a+b,0)!==100&&n===1)widths=[100];builderConfig.layout.widths=widths;layoutWidths.innerHTML='';for(let i=0;i<4;i++){const w=document.createElement('div');w.className='df-field';if(i>=n)w.hidden=true;w.innerHTML=`<label><?php echo addslashes(Text::_('COM_DECAROFORMS_COLUMN')); ?> ${i+1}</label><input type="number" min="0" max="100" data-width="${i}" value="${esc(widths[i]??0)}">`;w.querySelector('input').addEventListener('input',e=>{builderConfig.layout.widths[i]=Number(e.target.value||0);renderLayoutTotal();sync();});layoutWidths.appendChild(w);}renderLayoutTotal();sync();}
function renderLayoutTotal(){const total=(builderConfig.layout.widths||[]).slice(0,builderConfig.layout.columns).reduce((a,b)=>a+Number(b||0),0);layoutTotal.textContent=`Totale: ${total}%`;layoutTotal.classList.toggle('is-ok',total===100);layoutTotal.classList.toggle('is-error',total!==100);}
layoutColumns.addEventListener('change',()=>{builderConfig.layout.columns=Number(layoutColumns.value);builderConfig.layout.widths=Array.from({length:builderConfig.layout.columns},(_,i)=>builderConfig.layout.widths?.[i]??Math.floor(100/builderConfig.layout.columns));if(builderConfig.layout.columns===1)builderConfig.layout.widths=[100];renderLayout();});mobileStack.addEventListener('change',()=>{builderConfig.layout.mobile_stack=mobileStack.checked;sync();});document.querySelectorAll('[data-layout-preset]').forEach(b=>b.addEventListener('click',()=>{const w=b.dataset.layoutPreset.split(',').map(Number);builderConfig.layout.columns=w.length;builderConfig.layout.widths=w;renderLayout();}));document.getElementById('df-layout-apply').addEventListener('click',()=>{const widths=builderConfig.layout.widths.slice(0,builderConfig.layout.columns);selected.forEach((f,i)=>{defaultFieldConfig(f);const col=(i%builderConfig.layout.columns)+1,row=Math.floor(i/builderConfig.layout.columns)+1;f.config.layout={row,col,width:widths[col-1]||100};});renderSelected();});

// Statuses and columns.
function slugStatus(v){return String(v||'status').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,30)||'status';}const statusPalette=['#0d6efd','#f59e0b','#198754','#6c757d','#dc3545','#7c3aed','#0891b2'];
function renderStatuses(){statusEditor.innerHTML='';statuses.forEach((st,i)=>{st.color=/^#[0-9a-fA-F]{6}$/.test(st.color||'')?st.color:statusPalette[i%statusPalette.length];const r=document.createElement('div');r.className='df-status-row';r.innerHTML=`<input data-status-label value="${esc(st.label||'')}" placeholder="Stato"><input data-status-key value="${esc(st.key||'')}" placeholder="key"><div class="df-status-color-wrap"><input class="df-status-color" data-status-color type="color" value="${esc(st.color)}"><span class="df-status-color-value">${esc(st.color)}</span></div><button type="button" class="df-status-remove">×</button>`;const li=r.querySelector('[data-status-label]'),ki=r.querySelector('[data-status-key]'),ci=r.querySelector('[data-status-color]');li.oninput=()=>{st.label=li.value;if(!st.key){st.key=slugStatus(li.value);ki.value=st.key;}sync();};ki.oninput=()=>{st.key=slugStatus(ki.value);sync();};ci.oninput=()=>{st.color=ci.value.toLowerCase();r.querySelector('.df-status-color-value').textContent=st.color;sync();};r.querySelector('button').onclick=()=>{if(statuses.length>1){statuses.splice(i,1);renderStatuses();}};statusEditor.appendChild(r);});sync();}
document.getElementById('df-add-status').onclick=()=>{statuses.push({key:'status_'+(statuses.length+1),label:'Nuovo stato',color:statusPalette[statuses.length%statusPalette.length]});renderStatuses();};
function columnItems(){return [['_reference','<?php echo addslashes(Text::_('COM_DECAROFORMS_REFERENCE')); ?>'],['_email','<?php echo addslashes(Text::_('COM_DECAROFORMS_EMAIL')); ?>'],['_status','<?php echo addslashes(Text::_('COM_DECAROFORMS_STATUS')); ?>'],['_created_at','<?php echo addslashes(Text::_('COM_DECAROFORMS_DATE')); ?>'],['_payment','<?php echo addslashes(Text::_('COM_DECAROFORMS_PAYMENT')); ?>'],...selected.filter(x=>!['separator','pagebreak','page','heading','info','fieldset'].includes(x.type)).map(x=>[x.key,x.label])];}
function renderColumns(){const items=columnItems();columns=columns.filter(k=>items.some(i=>i[0]===k));if(!columns.length)columns=['_reference','_email','_status','_created_at'];columnList.innerHTML='';items.forEach(([key,label])=>{const d=document.createElement('label');d.className='df-column-item';d.innerHTML=`<input type="checkbox" ${columns.includes(key)?'checked':''}><span>${esc(label)}</span>`;d.querySelector('input').onchange=e=>{if(e.target.checked){if(!columns.includes(key))columns.push(key);}else columns=columns.filter(x=>x!==key);sync();};columnList.appendChild(d);});sync();}
document.getElementById('df-columns-all').onclick=()=>{columns=columnItems().map(i=>i[0]);renderColumns();};document.getElementById('df-columns-reset').onclick=()=>{columns=['_reference','_email','_status','_created_at'];renderColumns();};

// Email configuration and previews.
let lastTokenTarget=null;document.querySelectorAll('[data-email]').forEach(el=>{const path=el.dataset.email;el.addEventListener('focus',()=>lastTokenTarget=el);const ev=el.tagName==='SELECT'?'change':'input';el.addEventListener(ev,()=>{setDeep(emailConfig,path,el.value);sync();});});document.querySelectorAll('[data-email-check]').forEach(el=>el.addEventListener('change',()=>{setDeep(emailConfig,el.dataset.emailCheck,el.checked);sync();}));
const userConfirmation=document.getElementById('df-user-confirmation');userConfirmation.addEventListener('change',()=>{emailConfig.user.enabled=userConfirmation.checked;document.getElementById('df-user-email-settings').hidden=!userConfirmation.checked;sync();});
function renderUserEmailFields(){const s=document.getElementById('df-user-email-field'),emails=selected.filter(x=>x.type==='email'||x.key==='email');const current=emailConfig.user.to_field||emails[0]?.key||'email';s.innerHTML=emails.map(x=>`<option value="${esc(x.key)}" ${x.key===current?'selected':''}>${esc(x.label)}</option>`).join('')||'<option value="email">Email</option>';emailConfig.user.to_field=s.value||current;s.onchange=()=>{emailConfig.user.to_field=s.value;sync();};document.getElementById('df-user-email-settings').hidden=!userConfirmation.checked;sync();}
function renderTokens(){const p=document.getElementById('df-token-picker');const base=[['{form_title}','Titolo modulo'],['{form_id}','ID modulo'],['{reference}','Riferimento invio'],['{riferimento}','Riferimento pagamento'],['{data}','Data'],['{anno}','Anno'],['{all_fields}','Tutti i campi']];p.innerHTML=[...base,...selected.map(x=>[`{${x.key}}`,x.label])].map(([v,l])=>`<option value="${esc(v)}">${esc(l)} — ${esc(v)}</option>`).join('');}
document.getElementById('df-token-insert').onclick=()=>{if(!lastTokenTarget)return;const token=document.getElementById('df-token-picker').value;const s=lastTokenTarget.selectionStart??lastTokenTarget.value.length,e=lastTokenTarget.selectionEnd??s;lastTokenTarget.value=lastTokenTarget.value.slice(0,s)+token+lastTokenTarget.value.slice(e);lastTokenTarget.dispatchEvent(new Event('input',{bubbles:true}));lastTokenTarget.focus();};
function renderEmailPickers(){document.querySelectorAll('[data-email-picker]').forEach(box=>{const audience=box.dataset.emailPicker,config=emailConfig[audience];box.innerHTML='';templateDefs.forEach(([key,label])=>{const card=document.createElement('div');card.className='df-email-choice'+((config.template||'standard')===key?' is-active':'');card.innerHTML=`<button type="button" class="df-email-thumb" data-template="${key}" title="${esc(tr.preview)}"><span></span></button><label class="df-email-choice-foot"><input type="radio" name="df-email-template-${audience}" value="${key}" ${(config.template||'standard')===key?'checked':''}><span>${esc(label)}</span></label>`;card.querySelector('.df-email-thumb').onclick=()=>showEmailPreview(audience,key);card.querySelector('input').onchange=()=>{config.template=key;renderEmailPickers();renderEmailSpecial(audience);sync();};box.appendChild(card);});renderEmailSpecial(audience);});}
function renderEmailSpecial(audience){const box=document.querySelector(`[data-email-special="${audience}"]`),cfg=emailConfig[audience],t=cfg.template||'standard';box.hidden=!['custom','html','chatgpt'].includes(t);if(box.hidden){box.innerHTML='';return;}if(t==='custom'){const c=cfg.custom||{};box.innerHTML=`<div class="df-grid"><div class="df-field"><label><?php echo addslashes(Text::_('COM_DECAROFORMS_BASE_TEMPLATE')); ?></label><select data-special="base">${templateDefs.slice(0,8).map(([k,l])=>`<option value="${k}" ${(c.base||'standard')===k?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div class="df-field"><label><?php echo addslashes(Text::_('COM_DECAROFORMS_RADIUS')); ?> px</label><input type="number" min="0" max="40" data-special="radius" value="${esc(c.radius??8)}"></div>${[['primary','<?php echo addslashes(Text::_('COM_DECAROFORMS_PRIMARY_COLOR')); ?>'],['secondary','<?php echo addslashes(Text::_('COM_DECAROFORMS_SECONDARY_COLOR')); ?>'],['background','<?php echo addslashes(Text::_('COM_DECAROFORMS_BACKGROUND_COLOR')); ?>'],['text','<?php echo addslashes(Text::_('COM_DECAROFORMS_TEXT_COLOR')); ?>'],['button','<?php echo addslashes(Text::_('COM_DECAROFORMS_BUTTON_COLOR')); ?>'],['border','<?php echo addslashes(Text::_('COM_DECAROFORMS_BORDER_COLOR')); ?>']].map(([k,l])=>`<div class="df-field"><label>${l}</label><input type="color" data-special="${k}" value="${esc(c[k]||'#e60046')}"></div>`).join('')}</div><button class="df-btn df-small" type="button" data-reset-colors><?php echo addslashes(Text::_('COM_DECAROFORMS_RESET_COLORS')); ?></button>`;box.querySelectorAll('[data-special]').forEach(el=>el.oninput=()=>{cfg.custom=cfg.custom||{};cfg.custom[el.dataset.special]=el.type==='number'?Number(el.value):el.value;sync();});box.querySelector('[data-reset-colors]').onclick=()=>{cfg.custom={base:'standard',primary:'#e60046',secondary:'#26364a',background:'#ffffff',text:'#20262d',button:'#e60046',border:'#dfe3e7',radius:8};renderEmailSpecial(audience);sync();};}
if(t==='html'){box.innerHTML=`<label class="df-label">HTML libero</label><textarea class="df-codearea" data-email-html placeholder="<div>...</div>">${esc(cfg.html||'')}</textarea><div class="df-note"><?php echo addslashes(Text::_('COM_DECAROFORMS_HTML_VARIABLE_NOTE')); ?></div>`;box.querySelector('[data-email-html]').oninput=e=>{cfg.html=e.target.value;lastTokenTarget=e.target;sync();};box.querySelector('[data-email-html]').onfocus=e=>lastTokenTarget=e.target;}
if(t==='chatgpt'){box.innerHTML=`<div class="df-field"><label><?php echo addslashes(Text::_('COM_DECAROFORMS_CHATGPT_INSTRUCTIONS')); ?></label><textarea data-chatgpt-instructions placeholder="<?php echo addslashes(Text::_('COM_DECAROFORMS_CHATGPT_PLACEHOLDER')); ?>">${esc(cfg.chatgpt_instructions||'')}</textarea></div><div class="df-inline"><button class="df-btn df-small" type="button" data-copy-chatgpt>${esc(tr.copyPrompt)}</button><span class="df-note" data-copy-status></span></div><div class="df-field" style="margin-top:10px"><label><?php echo addslashes(Text::_('COM_DECAROFORMS_CHATGPT_HTML_RESULT')); ?></label><textarea class="df-codearea" data-chatgpt-html placeholder="<?php echo addslashes(Text::_('COM_DECAROFORMS_CHATGPT_PASTE_HTML')); ?>">${esc(cfg.html||'')}</textarea></div>`;box.querySelector('[data-chatgpt-instructions]').oninput=e=>{cfg.chatgpt_instructions=e.target.value;sync();};box.querySelector('[data-chatgpt-html]').oninput=e=>{cfg.html=e.target.value;sync();};box.querySelector('[data-copy-chatgpt]').onclick=async()=>{const prompt=buildChatGptPrompt(audience);try{await navigator.clipboard.writeText(prompt);box.querySelector('[data-copy-status]').textContent=tr.copied;}catch{box.querySelector('[data-copy-status]').textContent=prompt;}};}}
function buildChatGptPrompt(audience){const title=document.querySelector('[name="title"]')?.value||'Modulo';const cfg=emailConfig[audience];return `Crea un template HTML email responsive per il modulo "${title}".\nDestinatario: ${audience==='admin'?'amministrazione':'utente'}.\nIstruzioni: ${cfg.chatgpt_instructions||'Stile professionale, accessibile e compatibile con client email.'}\n\nCampi del modulo:\n${selected.map(x=>`- ${x.label}: {${x.key}} (${x.type})`).join('\n')}\n\nVariabili di sistema: {form_title}, {form_id}, {reference}, {riferimento}, {data}, {anno}, {all_fields}.\nRestituisci solo HTML inline-CSS, senza script e senza dati personali reali.`;}
function exampleValue(f){const map={first_name:'Mario',last_name:'Rossi',full_name:'Mario Rossi',email:'mario.rossi@example.com',phone:'+39 333 123 4567',mobile:'+39 333 123 4567',city:'Roma',region:'Lazio',postcode:'00100',nationality:'Italiana',member_number:'001234',role:'Consigliere'};return map[f.key]||f.options?.[0]||(['file','upload'].includes(f.type)?'documento.pdf':f.type==='date'?'04/09/2026':f.type==='number'?'1':'Esempio');}
function previewRows(){return selected.filter(f=>!['separator','pagebreak','page','heading','info','fieldset'].includes(f.type)).map(f=>`<tr><td style="padding:7px 9px;border-bottom:1px solid #e8ebef;font-weight:700;vertical-align:top">${esc(f.label)}</td><td style="padding:7px 9px;border-bottom:1px solid #e8ebef">${esc(exampleValue(f))}</td></tr>`).join('');}
function emailPreviewHtml(audience,template){const cfg=emailConfig[audience],title=document.querySelector('[name="title"]')?.value||'Modulo',subject=(cfg.subject|| (audience==='user'?'Abbiamo ricevuto il tuo invio – {form_title}':'Nuovo invio – {form_title}')).replaceAll('{form_title}',title),rows=`<table role="presentation" style="width:100%;border-collapse:collapse">${previewRows()}</table>`,intro=audience==='user'?`<p>Abbiamo ricevuto correttamente il tuo invio.</p>`:`<p>È stato ricevuto un nuovo invio.</p>`,content=`<h2 style="margin:0 0 6px">${esc(title)}</h2><p style="margin:0 0 14px;color:#667085">Riferimento: <strong>FRM-20260904-DEMO</strong></p>${intro}${rows}`,accent='#e60046';if(template==='html'||template==='chatgpt'){return cfg.html||`<div style="background:#fff;padding:22px;font-family:Arial">${content}</div>`;}if(template==='custom'){const c=cfg.custom||{},base=c.base||'standard';const inner=emailPreviewHtml(audience,base);return `<div style="background:${esc(c.background||'#fff')};color:${esc(c.text||'#20262d')};border:1px solid ${esc(c.border||'#dfe3e7')};border-radius:${Number(c.radius||8)}px;overflow:hidden"><div style="height:8px;background:${esc(c.primary||accent)}"></div>${inner}</div>`;}if(template==='minimal')return `<div style="font-family:Arial;background:#fff;padding:24px;color:#20262d">${content}</div>`;if(template==='institutional')return `<div style="font-family:Arial;background:#fff"><div style="background:#26364a;color:#fff;padding:15px 20px;font-weight:800">${esc(subject)}</div><div style="padding:22px">${content}</div></div>`;if(template==='card')return `<div style="font-family:Arial;padding:24px;background:#f2f4f7"><div style="background:#fff;border-radius:10px;padding:22px;box-shadow:0 4px 18px rgba(0,0,0,.1)">${content}</div></div>`;if(template==='compact')return `<div style="font-family:Arial;background:#fff;border-left:5px solid ${accent};padding:18px 20px">${content}</div>`;if(template==='modern')return `<div style="font-family:Arial;background:linear-gradient(135deg,#f7f8fa,#fff);padding:24px"><div style="background:#fff;border-radius:14px;padding:24px"><div style="width:54px;height:5px;background:${accent};border-radius:999px;margin-bottom:17px"></div>${content}</div></div>`;if(template==='elegant')return `<div style="font-family:Georgia,serif;background:#fbfaf7;border:1px solid #d8ccb0;padding:28px;color:#2d2922"><div style="text-align:center;letter-spacing:.08em;margin-bottom:18px">${esc(subject)}</div>${content}</div>`;if(template==='receipt')return `<div style="font-family:ui-monospace,monospace;background:#fff;padding:22px;border:1px dashed #aab2bc"><strong>${esc(subject)}</strong><hr style="border:0;border-top:1px dashed #aab2bc;margin:14px 0">${content}</div>`;return `<div style="font-family:Arial;background:#f4f5f7;padding:22px"><div style="background:#fff"><div style="background:${accent};color:#fff;padding:16px 20px;font-weight:800">${esc(subject)}</div><div style="padding:22px">${content}</div></div></div>`;}
const previewModal=document.getElementById('df-email-preview-modal');function showEmailPreview(audience,template){document.getElementById('df-preview-title').textContent=templateDefs.find(x=>x[0]===template)?.[1]||template;document.getElementById('df-preview-subject').textContent=audience==='admin'?'Email amministrazione':'Email utente';document.getElementById('df-preview-canvas').innerHTML=emailPreviewHtml(audience,template);previewModal.hidden=false;document.body.style.overflow='hidden';}document.querySelectorAll('[data-preview-close]').forEach(x=>x.onclick=()=>{previewModal.hidden=true;document.body.style.overflow='';});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!previewModal.hidden){previewModal.hidden=true;document.body.style.overflow='';}});

// Additional emails.
function newAdditional(){return {name:'',enabled:true,to:'',reply_to:'',reply_name:'',cc:'',bcc:'',subject:'Nuovo invio – {form_title}',template:'standard',html:'',auto_message:true,attach_uploads:false,condition:{field:'',operator:'eq',value:''}};}
function renderAdditional(){const box=document.getElementById('df-additional-list');box.innerHTML='';if(!additionalEmails.length){box.innerHTML=`<div class="df-note">${esc(tr.noAdditional)}</div>`;sync();return;}additionalEmails.forEach((m,i)=>{m.condition=m.condition||{field:'',operator:'eq',value:''};const d=document.createElement('div');d.className='df-additional-card';d.innerHTML=`<div class="df-additional-head"><strong>${esc(m.name||`${tr.newEmail} #${i+1}`)}</strong><div class="df-inline"><label class="df-check"><input type="checkbox" data-a-enabled ${m.enabled!==false?'checked':''}> Attiva</label><button class="df-btn df-small" type="button" data-a-remove>${esc(tr.remove)}</button></div></div><div class="df-additional-grid"><div class="df-field"><label>${esc(tr.emailName)}</label><input data-a="name" value="${esc(m.name||'')}"></div><div class="df-field"><label>To</label><input data-a="to" value="${esc(m.to||'')}"></div><div class="df-field"><label>Reply-To</label><input data-a="reply_to" value="${esc(m.reply_to||'')}"></div><div class="df-field"><label>CC / BCC</label><input data-a="cc" value="${esc(m.cc||'')}" placeholder="CC"><input data-a="bcc" value="${esc(m.bcc||'')}" placeholder="BCC" style="margin-top:5px"></div><div class="df-field full"><label><?php echo addslashes(Text::_('COM_DECAROFORMS_EMAIL_SUBJECT')); ?></label><input data-a="subject" value="${esc(m.subject||'')}"></div><div class="df-field"><label>${esc(tr.template)}</label><select data-a="template">${templateDefs.map(([k,l])=>`<option value="${k}" ${m.template===k?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div class="df-field"><label class="df-check"><input type="checkbox" data-a-check="attach_uploads" ${m.attach_uploads?'checked':''}> <?php echo addslashes(Text::_('COM_DECAROFORMS_ATTACH_UPLOADS')); ?></label></div><div class="df-field full"><label>${esc(tr.condition)}</label><div class="df-condition-row"><select data-a-cond="field"><option value="">Sempre</option>${fieldSelectOptions(m.condition.field||'')}</select><select data-a-cond="operator"><option value="eq" ${m.condition.operator==='eq'?'selected':''}>=</option><option value="neq" ${m.condition.operator==='neq'?'selected':''}>≠</option><option value="contains" ${m.condition.operator==='contains'?'selected':''}>contiene</option><option value="not_empty" ${m.condition.operator==='not_empty'?'selected':''}>non vuoto</option></select><input data-a-cond="value" value="${esc(m.condition.value||'')}" placeholder="Valore"><span></span></div></div>${['html','chatgpt'].includes(m.template)?`<div class="df-field full"><label>HTML</label><textarea class="df-codearea" data-a="html">${esc(m.html||'')}</textarea></div>`:''}</div>`;d.querySelector('[data-a-enabled]').onchange=e=>{m.enabled=e.target.checked;sync();};d.querySelector('[data-a-remove]').onclick=()=>{additionalEmails.splice(i,1);renderAdditional();};d.querySelectorAll('[data-a]').forEach(el=>{const ev=el.tagName==='SELECT'?'change':'input';el.addEventListener(ev,()=>{m[el.dataset.a]=el.value;if(el.dataset.a==='template')renderAdditional();sync();});});d.querySelectorAll('[data-a-check]').forEach(el=>el.onchange=()=>{m[el.dataset.aCheck]=el.checked;sync();});d.querySelectorAll('[data-a-cond]').forEach(el=>{const ev=el.tagName==='SELECT'?'change':'input';el.addEventListener(ev,()=>{m.condition[el.dataset.aCond]=el.value;sync();});});box.appendChild(d);});sync();}
document.getElementById('df-additional-add').onclick=()=>{additionalEmails.push(newAdditional());renderAdditional();};

// Builder configuration controls.
const controls={ajax:'df-validation-ajax',scroll_error:'df-validation-scroll',required_marker:'df-required-marker',error_message:'df-error-message'};document.getElementById(controls.ajax).checked=builderConfig.validation.ajax!==false;document.getElementById(controls.scroll_error).checked=builderConfig.validation.scroll_error!==false;document.getElementById(controls.required_marker).value=builderConfig.validation.required_marker||'*';document.getElementById(controls.error_message).value=builderConfig.validation.error_message||'';document.getElementById(controls.ajax).onchange=e=>{builderConfig.validation.ajax=e.target.checked;sync();};document.getElementById(controls.scroll_error).onchange=e=>{builderConfig.validation.scroll_error=e.target.checked;sync();};document.getElementById(controls.required_marker).oninput=e=>{builderConfig.validation.required_marker=e.target.value;sync();};document.getElementById(controls.error_message).oninput=e=>{builderConfig.validation.error_message=e.target.value;sync();};
const conf={enabled:document.getElementById('df-confirm-enabled'),position:document.getElementById('df-confirm-position'),scroll:document.getElementById('df-confirm-scroll'),cont:document.getElementById('df-confirm-continue'),label:document.getElementById('df-confirm-continue-label'),url:document.getElementById('df-confirm-continue-url')};conf.enabled.checked=builderConfig.confirmation.enabled!==false;conf.position.value=builderConfig.confirmation.position||'below';conf.scroll.checked=!!builderConfig.confirmation.scroll;conf.cont.checked=!!builderConfig.confirmation.continue;conf.label.value=builderConfig.confirmation.continue_label||'Continua';conf.url.value=builderConfig.confirmation.continue_url||'';conf.enabled.onchange=e=>{builderConfig.confirmation.enabled=e.target.checked;sync();};conf.position.onchange=e=>{builderConfig.confirmation.position=e.target.value;sync();};conf.scroll.onchange=e=>{builderConfig.confirmation.scroll=e.target.checked;sync();};conf.cont.onchange=e=>{builderConfig.confirmation.continue=e.target.checked;sync();};conf.label.oninput=e=>{builderConfig.confirmation.continue_label=e.target.value;sync();};conf.url.oninput=e=>{builderConfig.confirmation.continue_url=e.target.value;sync();};
const minSeconds=document.getElementById('df-min-seconds'),rateSeconds=document.getElementById('df-rate-seconds');minSeconds.value=builderConfig.security.min_seconds??2;rateSeconds.value=builderConfig.security.rate_seconds??8;minSeconds.oninput=e=>{builderConfig.security.min_seconds=Math.max(0,Number(e.target.value||0));sync();};rateSeconds.oninput=e=>{builderConfig.security.rate_seconds=Math.max(0,Number(e.target.value||0));sync();};
const sheetsEnabled=document.getElementById('df-sheets-enabled'),sheetsWebhook=document.getElementById('df-sheets-webhook'),sheetsSecret=document.getElementById('df-sheets-secret'),sheetsFiles=document.getElementById('df-sheets-files');sheetsEnabled.checked=!!integrations.google_sheets.enabled;sheetsWebhook.value=integrations.google_sheets.webhook_url||'';sheetsSecret.value=integrations.google_sheets.secret||'';sheetsFiles.checked=!!integrations.google_sheets.include_files;sheetsEnabled.onchange=e=>{integrations.google_sheets.enabled=e.target.checked;sync();};sheetsWebhook.oninput=e=>{integrations.google_sheets.webhook_url=e.target.value;sync();};sheetsSecret.oninput=e=>{integrations.google_sheets.secret=e.target.value;sync();};sheetsFiles.onchange=e=>{integrations.google_sheets.include_files=e.target.checked;sync();};
document.getElementById('df-add-calculation').onclick=()=>add({key:'calculation',type:'calculated',category:'values',label:'<?php echo addslashes(Text::_('COM_DECAROFORMS_FIELD_CALCULATION')); ?>',placeholder:'',help:'',default:'',options:[],required:false,config:{formula:'',decimals:2,prefix:'',suffix:'',visible:true}});

// Quick templates.
const libByKey=()=>Object.fromEntries(library.map(x=>[x.key,x]));const formTemplates={contact:['first_name','last_name','email','phone','subject','message','privacy_consent'],registration:['first_name','last_name','birth_date','email','phone','address','postcode','city','privacy_consent'],event:['first_name','last_name','email','event_date','participants','notes','privacy_consent'],membership:['first_name','last_name','birth_date','email','phone','address','postcode','city','member_number','privacy_consent'],reservation:['first_name','last_name','email','phone','event_date','participants','notes'],blank:[]};document.querySelectorAll('[data-form-template]').forEach(b=>b.onclick=()=>{const name=b.dataset.formTemplate;if(name==='blank'){selected=[];}else{const map=libByKey();selected=(formTemplates[name]||[]).map(k=>defaultFieldConfig(clone(map[k]))).filter(Boolean);selected.forEach((f,i)=>{f.key=uniqueKey(f.key);f.config.layout={row:i+1,col:1,width:100};});}renderSelected();renderColumns();renderTokens();renderUserEmailFields();renderAdditional();});

// Submit guard: layout widths must total 100.
document.getElementById('df-builder-form').addEventListener('submit',e=>{const total=(builderConfig.layout.widths||[]).slice(0,builderConfig.layout.columns).reduce((a,b)=>a+Number(b||0),0);if(total!==100){e.preventDefault();document.querySelectorAll('[data-accordion]')[3]?.classList.add('is-open');layoutTotal.scrollIntoView({behavior:'smooth',block:'center'});return;}sync();});

renderLibrary();renderSelected();renderLayout();renderStatuses();renderColumns();renderTokens();renderUserEmailFields();renderEmailPickers();renderAdditional();sync();
})();
</script>
